mapper.select:
SELECT pro.id, pro.code, pro.purchase_order_code AS purchaseOrderCode, pro.supplier_name AS supplierName, pro.approve_status AS approveStatus, pro.invalid_status AS invalidStatus, prod.id as detailId, prod.sku_id AS skuId, prod.sku_no AS skuNo, pro.bill_date AS billDate, pro.return_warehouse_id AS returnWarehouseId, pro.return_warehouse_name AS returnWarehouseName, prod.return_qty AS returnQty, prod.return_price AS returnPrice, prod.deduct_amount_qty AS deductAmountQty, prod.currency, prod.currency_symbol AS currencySymbol, pro.return_remark AS returnRemark, pro.return_mode AS returnMode, pro.purchase_user_id AS purchaseUserId, pro.purchase_user_name AS purchaseUserName, pro.return_user_name AS returnUserName, prod.remark, pro.approve_user_name AS approveUserName, pro.approve_time AS approveTime, pro.create_user_name AS createUserName, pro.create_time AS createTime, prod.remark, prod.warehouse_location AS warehouseLocation, pro.source_type AS sourceType, pro.purchase_order_id AS purchaseOrderId, prod.purchase_order_detail_id AS purchaseOrderDetailId, pro.confirm_status AS confirmStatus, pro.unusual_type, pro.unusual_remark, pro.unusual_handle_user_id, pro.unusual_handle_user_name, pro.confirm_date, pro.return_type, prod.is_combination as isCombination, po.type as purchaseType, po.source_id as purchaseSourceId, po.source_code as purchaseSourceCode, po.source_type as purchaseSourceType, po.subcontract_type as subcontractType FROM po_return_detail prod INNER JOIN po_return pro ON prod.main_id = pro.id AND pro.is_deleted = FALSE LEFT JOIN purchase_order po ON pro.purchase_order_id = po.id AND po.is_deleted = FALSE WHERE ${params.sqlMap.default} and pro.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
pro.create_time desc,pro.id

SELECT pro.approve_status, prod.sku_id, prod.sku_no, pro.purchase_order_id, SUM(wrd.return_qty) AS returnQty FROM po_return_detail prod LEFT JOIN po_return pro ON prod.main_id = pro.id AND prod.is_deleted = FALSE WHERE pro.is_deleted = FALSE
AND wr.purchase_order_id = #{purchaseOrderId}
GROUP BY pro.approve_status, prod.sku_id, prod.sku_no, pro.purchase_order_id

SELECT pro.id, pro.code, pro.purchase_order_code AS purchaseOrderCode, pro.supplier_name AS supplierName, pro.approve_status AS approveStatus, pro.invalid_status AS invalidStatus, prod.sku_id AS skuId, prod.sku_no AS skuNo, pro.bill_date AS billDate, pro.return_warehouse_id AS returnWarehouseId, pro.return_warehouse_name AS returnWarehouseName, prod.return_qty AS returnQty, prod.return_price AS returnPrice, prod.deduct_amount_qty AS deductAmountQty, prod.currency, prod.currency_symbol AS currencySymbol, pro.return_remark AS returnRemark, pro.return_mode AS returnMode, pro.purchase_user_id AS purchaseUserId, pro.return_user_name AS returnUserName, prod.remark, pro.approve_user_name AS approveUserName, pro.approve_time AS approveTime, pro.create_user_name AS createUserName, pro.create_time AS createTime, prod.remark, prod.warehouse_location AS warehouseLocation, pro.source_type AS sourceType, prod.purchase_order_detail_id AS purchaseOrderDetailId, pro.confirm_status AS confirmStatus, pro.unusual_type, pro.unusual_remark, pro.unusual_handle_user_id, pro.unusual_handle_user_name, pro.confirm_date, prod.is_combination as isCombination FROM po_return_detail prod LEFT JOIN po_return pro ON prod.main_id = pro.id AND prod.is_deleted = FALSE WHERE ${params.sqlMap.default} and pro.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
pro.create_time desc,pro.id

select count(distinct pro.id) FROM po_return_detail prod LEFT JOIN po_return pro ON prod.main_id = pro.id AND prod.is_deleted = FALSE WHERE pro.is_deleted = FALSE
and pro.approve_status in
#{item}
and pro.invalid_status = #{params.invalidStatus}
AND pro.bill_date >= #{params.billDateList[0]} AND (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > pro.bill_date
${params.permissionSql}

select count(distinct pro.id) FROM po_return_detail prod LEFT JOIN po_return pro ON prod.main_id = pro.id AND prod.is_deleted = FALSE WHERE pro.is_deleted = FALSE
and pro.approve_status in
#{item}
and pro.invalid_status = #{params.invalidStatus}
AND pro.bill_date >= #{params.billDateList[0]} AND (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > pro.bill_date
${params.permissionSql}

SELECT DISTINCT pro.id, pro.code, pro.approve_status, pro.supplier_name, pro.return_warehouse_name, pro.create_time FROM po_return_detail prod INNER JOIN po_return pro ON prod.main_id = pro.id AND prod.is_deleted = FALSE WHERE pro.is_deleted = FALSE AND pro.invalid_status = FALSE
and pro.approve_status in
#{item}
AND pro.bill_date >= #{params.billDateList[0]} AND (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > pro.bill_date
${params.permissionSql}
${item.field} ${item.sort}
ORDER BY pro.create_time desc

SELECT pro.id, prod.id AS detailId, pro.confirm_date AS confirmDate, pro.return_mode AS returnMode, pro.code AS code, pro.purchase_order_code AS purchaseOrderCode, pro.confirm_status AS confirmStatus, prod.sku_id AS skuId, prod.sku_no AS skuNo, prod.return_qty AS returnQty, pro.return_remark AS returnRemark, prod.remark AS remark, pro.return_user_name AS returnUserName, pro.unusual_type AS unusualType, pro.unusual_remark AS unusualRemark, pro.bill_date AS billDate, pro.source_type AS sourceType FROM po_return_detail prod INNER JOIN po_return pro ON prod.main_id = pro.id AND prod.is_deleted = FALSE WHERE ${params.sqlMap.default} and pro.is_deleted = FALSE AND pro.approve_status = 'approve'
AND pro.supplier_id = #{params.supplierId}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
pro.create_time desc,pro.id

SELECT confirm_status AS tabFlag, count(*) AS count FROM po_return WHERE is_deleted=FALSE AND approve_status = 'approve'
AND supplier_id = #{params.supplierId}
GROUP BY confirm_status

select EXTRACT(MONTH FROM pr.bill_date) AS month, count(distinct pr.id) AS returnCount, sum(prd.return_qty) AS returnSkuCount, sum(case when pr.source_type = 'qcInfo' then prd.return_qty else 0 end) AS qcReturnSkuCount, sum(prd.return_qty * prd.return_price) AS returnMoney from po_return pr inner join po_return_detail prd on pr.id = prd.main_id and prd.is_deleted = false where pr.supplier_id = #{params.surpplierId} and pr.approve_status = 'approve'
and pr.bill_date >= #{params.startTime}
and pr.bill_date <= #{params.endTime}
and pr.is_deleted = false group by EXTRACT(MONTH FROM pr.bill_date)

SELECT pr.id FROM po_return pr WHERE pr.is_deleted = FALSE AND pr.approve_status = 'approve' AND pr.confirm_status = 'waitConfirm' AND
now() - make_interval(hours => #{item.returnConfirmDTO.duration} :: int) > pr.approve_time AND pr.supplier_id = #{item.supplierId}
now() - make_interval(mins => #{item.returnConfirmDTO.duration} :: int) > pr.approve_time AND pr.supplier_id = #{item.supplierId}
now() - make_interval(secs => #{item.returnConfirmDTO.duration} :: int) > pr.approve_time AND pr.supplier_id = #{item.supplierId}

select prd.id,prd.return_qty,prd.main_id,prd.purchase_order_detail_id from po_return pr inner join po_return_detail prd on pr.id = prd.main_id where pr.is_deleted = false and prd.is_deleted = false and pr.source_type = 'qcInfo' and pr.approve_status in
#{item}
and prd.purchase_order_detail_id in
#{item}

SELECT po.id as purchaseId, po.code as purchaseCode, pr.id as returnId, pr.code as returnCode, po.source_id as subcontractId, po.source_code as subcontractCode, pr.supplier_id as supplierId, pr.supplier_name as supplierName, po.approve_status as approveStatus, prd.sku_id, prd.sku_no FROM po_return pr LEFT JOIN po_return_detail prd ON pr.id = prd.main_id AND prd.is_deleted = FALSE LEFT JOIN purchase_order po ON po.id = pr.purchase_order_id AND po.is_deleted = FALSE
po."type" = 'CGDD02_SYS' AND po.invalid_status = false
AND pr.purchase_order_id = #{purchaseOrderId}

SELECT supplier_id,sku_id,tax_price,tax_rate,currency,currency_symbol,approve_time,purchase_org_id FROM ( SELECT pi.supplier_id, pid.sku_id, pid.tax_price, pid.tax_rate, pid.currency, pid.currency_symbol, pi.approve_time, po.purchase_org_id, ROW_NUMBER ( ) OVER ( PARTITION BY pi.supplier_id, pid.sku_id, po.purchase_org_id ORDER BY pi.approve_time DESC ) AS row_num FROM po_instock pi LEFT JOIN po_instock_detail pid ON pi.ID = pid.main_id AND pid.is_deleted = FALSE INNER JOIN purchase_order po ON pi.purchase_order_id = po.ID AND po."type" != 'CGDD06-SYS'
1=1
and pid.sku_id in
#{item}
and pi.supplier_id in
#{item}
and po.purchase_org_id in
#{item}
) M WHERE row_num = 1
